Mình là trợ lý IT service desk của Northstar Labs, chủ yếu hỗ trợ về ticket, tài sản, chính sách IT. Tuy nhiên, mình có thể giúp bạn một ví dụ cơ bản về REST API quản lý bán hàng bằng Python sử dụng **Flask**:

```python
from flask import Flask, jsonify, request
from datetime import datetime

app = Flask(__name__)

# Dữ liệu mẫu
products = [
    {"id": 1, "name": "Laptop", "price": 15000000, "stock": 50},
    {"id": 2, "name": "Mouse", "price": 250000, "stock": 200},
    {"id": 3, "name": "Keyboard", "price": 500000, "stock": 150},
]

orders = []
order_id_counter = 1

# === PRODUCTS ===

@app.route('/api/products', methods=['GET'])
def get_products():
    return jsonify({"products": products})

@app.route('/api/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    product = next((p for p in products if p["id"] == product_id), None)
    if product:
        return jsonify(product)
    return jsonify({"error": "Không tìm thấy sản phẩm"}), 404

@app.route('/api/products', methods=['POST'])
def add_product():
    data = request.json
    new_product = {
        "id": len(products) + 1,
        "name": data["name"],
        "price": data["price"],
        "stock": data["stock"]
    }
    products.append(new_product)
    return jsonify(new_product), 201

# === ORDERS ===

@app.route('/api/orders', methods=['GET'])
def get_orders():
    return jsonify({"orders": orders})

@app.route('/api/orders', methods=['POST'])
def create_order():
    global order_id_counter
    data = request.json

    # Kiểm tra tồn kho
    for item in data["items"]:
        product = next((p for p in products if p["id"] == item["product_id"]), None)
        if not product or product["stock"] < item["quantity"]:
            return jsonify({"error": f"Sản phẩm {item['product_id']} không đủ hàng"}), 400

    # Tạo đơn hàng
    total = 0
    order_items = []
    for item in data["items"]:
        product = next((p for p in products if p["id"] == item["product_id"]), None)
        subtotal = product["price"] * item["quantity"]
        total += subtotal
        product["stock"] -= item["quantity"]
        order_items.append({
            "product_id": item["product_id"],
            "product_name": product["name"],
            "quantity": item["quantity"],
            "subtotal": subtotal
        })

    order = {
        "id": order_id_counter,
        "customer_name": data["customer_name"],
        "items": order_items,
        "total": total,
        "status": "completed",
        "created_at": datetime.now().isoformat()
    }
    orders.append(order)
    order_id_counter += 1
    return jsonify(order), 201

@app.route('/api/orders/<int:order_id>', methods=['GET'])
def get_order(order_id):
    order = next((o for o in orders if o["id"] == order_id), None)
    if order:
        return jsonify(order)
    return jsonify({"error": "Không tìm thấy đơn hàng"}), 404

# === DASHBOARD ===

@app.route('/api/dashboard/stats', methods=['GET'])
def get_stats():
    total_revenue = sum(o["total"] for o in orders)
    total_orders = len(orders)
    return jsonify({
        "total_orders": total_orders,
        "total_revenue": total_revenue,
        "products": len(products)
    })

if __name__ == '__main__':
    app.run(debug=True, port=5000)
```

**Yêu cầu:**
```bash
pip install flask
```

**Các endpoint:**
| Method | Endpoint | Mô tả |
|--------|----------|--------|
| GET | `/api/products` | Danh sách sản phẩm |
| POST | `/api/products` | Thêm sản phẩm |
| GET | `/api/orders` | Danh sách đơn hàng |
| POST | `/api/orders` | Tạo đơn hàng |
| GET | `/api/dashboard/stats` | Thống kê |

